export function load(){try{let s=JSON.parse(localStorage.getItem(KEY));const arrays=['tasks','messages','docs','events','meetings','activity','applied'];if(s?.version!==3||!arrays.every(k=>Array.isArray(s[k]))||!s.docs.length||!s.meetings.length) return seed();
if(!s.tasks.every(t=>t.id&&t.title&&people.includes(t.owner)&&statuses.includes(t.status)&&Array.isArray(t.checklist)&&Array.isArray(t.comments))||!s.messages.every(m=>m.id&&m.body&&m.channel&&Array.isArray(m.replies)&&Array.isArray(m.reactions))||!s.docs.every(d=>d.id&&typeof d.content==='string'&&typeof d.title==='string')||!s.events.every(e=>e.id&&e.date&&e.time&&Array.isArray(e.attendees)&&e.duration>0)||!s.meetings.every(m=>s.events.some(e=>e.id===m.eventId)&&Array.isArray(m.agenda)&&Array.isArray(m.actionTaskIds))||!s.activity.every(a=>a.id&&a.title&&a.type)||typeof s.profile!=='string'||!s.demoDate) return seed();
s.docs=s.docs.map(d=>({...d,content:d.content.replace(/Northstar/g,'Loop')}));s.drafts=s.drafts&&typeof s.drafts==='object'?s.drafts:{};s.docComments=s.docComments&&typeof s.docComments==='object'?s.docComments:{};return s}catch{return seed()}}
export let state=load();
export function save(){try{localStorage.setItem(KEY,JSON.stringify(state));return true}catch{return false}}
export function reset(){state=seed();save()}
export function uid(p='id'){return p+'-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,6)}
export function activity(title,detail,type,ref){state.activity.unshift({id:uid('a'),title,detail,type,ref,read:false,time:new Date().toLocaleTimeString([],{hour:'numeric',minute:'2-digit'})})}
export function createTask(data){const task={id:uid('t'),status:'Backlog',priority:'Medium',checklist:[],comments:[],...data};state.tasks.push(task);activity('Task created: '+task.title,task.owner+' · '+task.project,'task',task.id);save();return task}
export function updateTask(id,data){let t=state.tasks.find(t=>t.id===id);if(!t)return;const done=t.status!=='Done'&&data.status==='Done';Object.assign(t,data);if(done)activity('Completed: '+t.title,t.project,'task',t.id);save()}
export function createEvent(data){let id=uid('e'),mid=uid('mt');let e={...data,id,meetingId:mid};state.events.push(e);state.meetings.push({id:mid,eventId:id,docId:'d3',agenda:['Review progress','Agree on next steps'],notes:'Add your meeting notes here.',summary:false,actionTaskIds:[]});activity('Meeting scheduled: '+e.title,e.date+' at '+e.time,'meetings',mid);save();return e}
